<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/csrf.php';require_role('administrador');$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$n=trim($_POST['nombres']??'');$a=trim($_POST['apellidos']??'');$u=trim($_POST['usuario']??'');$mail=trim($_POST['correo']??'');$pass=$_POST['password']??'';$role=(int)($_POST['id_rol']??0);
 if(!$n||!$a||!$u||!filter_var($mail,FILTER_VALIDATE_EMAIL)||strlen($pass)<10||$role<1)$errors[]='Completa todos los campos. La contraseña debe tener al menos 10 caracteres.';
 if(!$errors){try{$st=$pdo->prepare('INSERT INTO usuarios(id_rol,nombres,apellidos,usuario,correo,password_hash,estado,fecha_creacion) VALUES(?,?,?,?,?,?,\'activo\',NOW())');$st->execute([$role,$n,$a,$u,$mail,password_hash($pass,PASSWORD_DEFAULT)]);log_event($pdo,(int)current_user()['id'],'USUARIO_CREADO','Se creó la cuenta '.$u.'.');flash('success','Usuario creado correctamente.');redirect('usuarios.php');}catch(PDOException $ex){$errors[]='No se pudo crear. Verifica que el usuario y correo no estén registrados.';}}
}
$roles=$pdo->query('SELECT * FROM roles ORDER BY id_rol')->fetchAll();$users=$pdo->query('SELECT u.id_usuario,u.nombres,u.apellidos,u.usuario,u.correo,u.estado,r.nombre AS role FROM usuarios u JOIN roles r ON r.id_rol=u.id_rol ORDER BY u.id_usuario DESC')->fetchAll();$pageTitle='Usuarios';require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><div class="eyebrow">ADMINISTRACIÓN</div><h1 class="page-title">Usuarios y perfiles</h1><p class="text-secondary">Crea cuentas y asigna uno de los cinco perfiles disponibles.</p></div><?php if($errors): ?><div class="alert alert-danger"><?php foreach($errors as $er): ?><?= e($er) ?><br><?php endforeach; ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-5"><div class="content-card"><h2 class="section-title">Crear usuario</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="mb-3"><label class="form-label">Nombres</label><input class="form-control" name="nombres" required></div><div class="mb-3"><label class="form-label">Apellidos</label><input class="form-control" name="apellidos" required></div><div class="mb-3"><label class="form-label">Usuario</label><input class="form-control" name="usuario" required></div><div class="mb-3"><label class="form-label">Correo</label><input class="form-control" type="email" name="correo" required></div><div class="mb-3"><label class="form-label">Contraseña temporal</label><input class="form-control" type="password" name="password" minlength="10" required></div><div class="mb-3"><label class="form-label">Perfil</label><select class="form-select" name="id_rol" required><option value="">Seleccionar</option><?php foreach($roles as $r): ?><option value="<?= (int)$r['id_rol'] ?>"><?= e(ucfirst($r['nombre'])) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary w-100">Crear cuenta</button></form></div></div><div class="col-lg-7"><div class="content-card"><h2 class="section-title">Cuentas registradas</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Usuario</th><th>Correo</th><th>Perfil</th><th>Estado</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= e($u['nombres'].' '.$u['apellidos']) ?></td><td><?= e($u['usuario']) ?></td><td><?= e($u['correo']) ?></td><td><?= e(ucfirst($u['role'])) ?></td><td><?= e($u['estado']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
